head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS23200.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명 : 중도상환(부분) 신고내역 조회
 ***********************************************/
scwin.fn_Search = function() {
    if (!$c.stf.compareFromToDate2(edt_FromDt, edt_ToDt)) {
        return;
    }

    // 오늘 16시 이후에 업로드된 데이터가 있는지 체크. 없으면 알럿 발생.
    scwin.fn_isExistUploadedKsdData();
    var param = '';
    param += "&{P}V_STD_CD=" + $c.stf.getObjectValue(txb_StdCd); //표준코드
    param += "&{P}V_ISU_NM=" + $c.stf.getObjectValue(txb_IsuNm); //종목명
    param += "&{P}V_FROM_DT=" + $c.stf.getObjectValue(edt_FromDt); //From Date
    param += "&{P}V_TO_DT=" + $c.stf.getObjectValue(edt_ToDt); //To Date
    param += "&{P}V_PROCS_TP=" + $c.stf.getObjectValue(cmb_ProcsTp); //처리구분

    var dsNm = 'BNS_HALFWY_REDMPT_DECL_DTL_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectHalfwyRedmptDeclDtlList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List1, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List1);
};
scwin.fn_SearchTab1 = function() {
    var std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    var redmpt_dd = dts_List1.getCellData(dts_List1.getRowPosition(), "KSD_REDMPT_DD");
    var param = '';
    param += "&{P}V_STD_CD=" + std_cd; //표준코드
    param += "&{P}V_FROM_DT=" + redmpt_dd; //From Date
    param += "&{P}V_TO_DT=" + redmpt_dd; //To Date

    var dsNm = 'BNS_KSD_RGHT_EXER_DTL_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectKsdRghtExerDtlList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ListTab1, dsNm, qryId, param);
};
scwin.fn_SearchTab2 = function() {
    var std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    var redmpt_dd = dts_List1.getCellData(dts_List1.getRowPosition(), "KSD_REDMPT_DD");
    var param = '';
    param += "&{P}V_STD_CD=" + std_cd; //표준코드
    param += "&{P}V_FROM_DT=" + redmpt_dd; //From Date
    param += "&{P}V_TO_DT=" + redmpt_dd; //To Date

    var dsNm = 'BNS_KSD_EARLY_REDMPT_DTL_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectKsdEarlyRedmptDtlList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ListTab2, dsNm, qryId, param);
};
scwin.fn_SearchTab3 = function() {
    var std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    var redmpt_dd = dts_List1.getCellData(dts_List1.getRowPosition(), "KSD_REDMPT_DD");
    var param = '';
    param += "&{P}V_STD_CD=" + std_cd; //표준코드
    param += "&{P}V_FROM_DT=" + redmpt_dd; //From Date
    param += "&{P}V_TO_DT=" + redmpt_dd; //To Date

    var dsNm = 'BNS_KSD_PRINCINT_PAY_DTL_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectKsdPrincintPayDtlList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ListTab3, dsNm, qryId, param);
};


/********************************************** 
 * 설명 : 채권신고담당자 조회
 ***********************************************/
scwin.fn_Search2 = function() {
    var isur_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "ISUR_CD");
    var dsNm = 'BNS_BND_DECL_CHRG_LIST';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    var param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List3, dsNm, qryId, param);
};


/********************************************** 
 * 설명 : 오늘 16시 이후에 업로드된 예탁원 데이터가 존재하는지 체크
 *           없으면 alert 발생..
 ***********************************************/
scwin.fn_isExistUploadedKsdData = function() {
    dts_check.SyncLoad = "True";
    var param = '';
    param += "&{P}V_TP=HALFWY"; // 구분 : HALFWY : 중도상환

    var dsNm = 'BNS_IS_EXIST_UPLOADED_KSD_DATA';
    var qryId = 'lds.stf.bnsdecl_mgr.select.selectUploadedKsdHalfwyData';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_check, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_GetParListBndIsu
 * 설명       : 상장종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: "",
        ISU_NM: $c.stf.getObjectValue(txb_IsuNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParListBndIsu
 * 설명       : 상장종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParListBndIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_StdCd, arrPar[0].STD_CD);
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].ISU_NM);
};


/********************************************** 
 * 함수명   : fn_OnColumnChanged
 * 설명       : dts_List1 데이터 값이 변경되었을때
 ***********************************************/
scwin.fn_OnColumnChanged = function(row, colid) {
    if (colid == "BND_MKTACT_TP_CD") {
        dts_List1.setCellData(row, "PROCS_TP", "E"); // 처리완료

        var bnd_mktact_tp_cd = dts_List1.getCellData(row, "BND_MKTACT_TP_CD");
        if (bnd_mktact_tp_cd == "311") {
            dts_List1.setCellData(row, "REDMPT_DD", dts_List1.getCellData(row, "KSD_REDMPT_DD"));
            dts_List1.setCellData(row, "REDMPT_AMT", "");
        } else {
            dts_List1.setCellData(row, "REDMPT_AMT", dts_List1.getCellData(row, "KSD_REDMPT_AMT"));
            dts_List1.setCellData(row, "REDMPT_DD", "");
        }
    }
};




/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 중도상환신고관리 처리완료 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    if (!$c.cp.isModified(dts_List1)) {
        $c.win.alert("변경된 내역이 없습니다.");
        return;
    }

    // 필수입력값 체크
    // RowStatus : 0 -> 변경사항 없음, 3 -> 수정
    for (var i = 1; i <= dts_List1.getTotalRow(); i++) {
        if (dts_List1.getRowStatus(i) != 0) {
            if (dts_List1.getCellData(i, "BND_MKTACT_TP_CD") == "") {
                $c.win.alert("시장조치를 선택하세요.");
                return;
            }
            if (dts_List1.getCellData(i, "REMK") == "") {
                $c.win.alert("변경 사유를 입력하세요.");
                return;
            }
        }
    }
    var url;
    if (!confirm("처리완료 하시겠습니까?")) return;
    url = "/bns/IsuChgEtc.do?method=priorredmptDeclAdmProcessComplt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List1)";
    trs_Save.Post();
};


/**
 * 처리완료 처리한건은 배경색 변경
 */
scwin.fn_ChangeGridBgColor = function() {
    //그리드 컬럼 ID 구하기
    var arrColID = [];
    for (var i = 0; i < grd_List1.getTotalCol(); i++) {
        arrColID.push(grd_List1.getColumnID(i));
    }

    //이 화면에서 처리완료한건들은 배경색 변경
    for (var j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_List1, arrColID[j], 'BgColor', "{decode(PROCS_YN,'Y','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(panel_Top);
    $c.bns.BnsPanelToGroupBox(panel_1);
    edt_FromDt.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 2));
    edt_ToDt.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));

    // 처리완료 처리한건은 배경색 변경
    scwin.fn_ChangeGridBgColor();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_List1_OnRowPosChanged = function(row) {
    if (dts_List1.getTotalRow() < 1) return;
    var tp = dts_List1.getCellData(row, "TP");
    // T1 : 권리행사내역, T2 : 조기상환내역, T3 : 원리급지급내역
    if (tp == "T1") {
        tab_Main.setSelectedTabIndex(1);
        scwin.fn_SearchTab1();
    } else if (tp == "T2") {
        tab_Main.setSelectedTabIndex(2);
        scwin.fn_SearchTab2();
    } else if (tp == "T3") {
        tab_Main.setSelectedTabIndex(3);
        scwin.fn_SearchTab3();
    }

    // 채권 신고담당자 조회
    scwin.fn_Search2();
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List1);
};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    //CloseWin(rowcount, grd_List3); 

};
scwin.btn_ISU_CD_SEARCH_onclick = function() {
    scwin.fn_GetPar = fn_GetParListBndIsu;
    scwin.fn_SetPar = fn_SetParListBndIsu;
    $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
};
scwin.txb_StdCd_onkeypress = function() {
    if (window.event.keyCode == 13 && $c.stf.getObjectValue(txb_StdCd) != "") {
        scwin.fn_Search();
    }
};
scwin.txb_StdCd_onchange = function() {
    $c.stf.setObjectValue(txb_IsuNm, "");
};
scwin.txb_IsuNm_onchange = function() {
    $c.stf.setObjectValue(txb_StdCd, "");
};
scwin.txb_IsuNm_onkeypress = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_GetPar = fn_GetParListBndIsu;
        scwin.fn_SetPar = fn_SetParListBndIsu;
        $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
    }
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_FromDt);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_ToDt);
};
scwin.dts_List1_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List3_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_check_OnLoadCompleted = function(rowcount) {
    if (rowcount < 1 || dts_check.getCellData(dts_check.getRowPosition(), "IS_EXIST") == "N") {
        var msg = "금일 예탁원의 채권 상환정보(엑셀 파일) 업로드가\n필요합니다.\n\n";
        msg += "예탁원 증권정보포탈(seibro.or.kr)에서\n";
        msg += "채권 상환정보 엑셀파일 3건* 에 대해 다운로드 후\n";
        msg += "채권상장시스템(bonds.krx.co.kr)에 업로드 조치 바랍니다.\n\n";
        msg += "* ①주식관련사채 권리행사내역\n  ②옵션부채권조기상환내역\n  ③원리금지급내역";
        $c.win.alert(msg);
    }
};
scwin.image_1_onclick = function() {
    if (dts_List1.getTotalRow() < 1) {
        return;
    }
    var std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    var procs_tp = dts_List1.getCellData(dts_List1.getRowPosition(), "PROCS_TP"); // 처리현황
    var bnd_mktact_tp_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "BND_MKTACT_TP_CD"); // 시장조치코드

    if (bnd_mktact_tp_cd == "303") {
        var url = "/bnschg/ULDBNS10500.gfm?STD_CD=" + std_cd + "&PROCS_TP=" + procs_tp;
        $c.frame.path("../").GWinOpen("BNS10700", url, "중도상환(부분)_BNS10500", 0, 0, 1300, 800, "");
    } else if (bnd_mktact_tp_cd == "304") {
        var url = "/bnschg/ULDBNS10600.gfm?STD_CD=" + std_cd + "&PROCS_TP=" + procs_tp;
        $c.frame.path("../").GWinOpen("BNS10600", url, "중도상환(전액)_BNS10600", 0, 0, 1300, 800, "");
    } else if (bnd_mktact_tp_cd == "311") {
        var url = "/bnsisuchg/ULDBNS15400.gfm?STD_CD=" + std_cd + "&PROCS_TP=" + procs_tp;
        $c.frame.path("../").GWinOpen("BNS15400", url, "상환일 변경_BNS15400", 0, 0, 1300, 800, "");
    }
};
scwin.dts_List1_OnColumnChanged = function(row, colid) {
    scwin.fn_OnColumnChanged(row, colid);
};
scwin.image_3_onclick = function() {
    scwin.fn_ProcsComplt();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
    scwin.fn_Search();
};
